import{_ as l,o as i,c as n,a5 as e}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"第12章 レンダリングパイプラインとシェーダ","description":"","frontmatter":{"title":"第12章 レンダリングパイプラインとシェーダ","study":{"source":"IT教本","status":"outline","summary":"頂点から画像までの処理段階と、各段階を記述するシェーダを学ぶための学習計画・概要です。概説で工程を整理した後、本文と小さなシェーダ実験を往復します。\\n\\n## 関連する辞典本文・実践\\n\\n- [レンダリングパイプライン全体像](/graphics/pipeline/overview.html)か","section":"learning","format":"path","domain":"graphics","collection":"low-level","order":13}},"headers":[],"relativePath":"guide/low-level/rendering-pipeline-shaders.md","filePath":"guide/low-level/rendering-pipeline-shaders.md"}'),s={name:"guide/low-level/rendering-pipeline-shaders.md"};function t(r,a,o,d,p,h){return i(),n("div",null,[...a[0]||(a[0]=[e(`<div id="第12章-レンダリングパイプラインとシェーダ-──-頂点からピクセルまで" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第12章-レンダリングパイプラインとシェーダ" tabindex="-1">第12章 レンダリングパイプラインとシェーダ <a class="header-anchor" href="#第12章-レンダリングパイプラインとシェーダ" aria-label="Permalink to &quot;第12章 レンダリングパイプラインとシェーダ&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>頂点から画像までの処理段階と、各段階を記述するシェーダを学ぶための<strong>学習計画・概要</strong>です。概説で工程を整理した後、本文と小さなシェーダ実験を往復します。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン全体像</a>から、各段階の本文へ進めます。</li><li><a href="/study/graphics/shader/hlsl.html">HLSL</a>と<a href="/study/graphics/shader/glsl.html">GLSL</a>では、言語とコンパイル経路を調べられます。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>「画面にゲームが表示される」の中身がこの章だ。三角形の頂点データが どんな段階を経て液晶の1ピクセルの色になるのか ── この変換の連鎖を 知らないままマテリアルを組むのは、文法を知らずに外国語を話すのに等しい。 RenderDocで1フレームを追える(最終目標)とは、<strong>このパイプラインの 各段階を画面上で識別できる</strong>ということである。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>グラフィックスパイプライン全段を順番に説明できる</li><li>HLSL/GLSLで頂点シェーダ・ピクセルシェーダを書ける</li><li>深度バッファ・アルファブレンド・カリングの原理と設定を説明できる</li><li>ライティングの基礎(ランバート、スペキュラ、法線マップ、PBRの概念)を実装できる</li><li>フォワード/ディファードレンダリングの違いと選択理由を説明できる</li><li>RenderDocで各パイプライン段階の入出力を検査できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第10章(ベクトル・行列・MVP変換)、第11章(GPU)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>パイプライン全景(暗唱レベルにする)</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>頂点バッファ/インデックスバッファ (VRAM)</span></span>
<span class="line"><span>  → [入力アセンブラ IA]     頂点を読み集める</span></span>
<span class="line"><span>  → [頂点シェーダ VS]       MVP変換・スキニング (プログラマブル)</span></span>
<span class="line"><span>  → (テッセレーション/ジオメトリ/メッシュシェーダ)  (任意)</span></span>
<span class="line"><span>  → [クリッピング/透視除算/ビューポート変換]  NDC→スクリーン</span></span>
<span class="line"><span>  → [ラスタライザ]          三角形→ピクセル候補(固定機能)</span></span>
<span class="line"><span>     属性の透視補正付き補間(UV・法線・色)</span></span>
<span class="line"><span>  → [ピクセルシェーダ PS]   色を計算 (プログラマブル)</span></span>
<span class="line"><span>  → [出力マージャ OM]       深度テスト・ステンシル・ブレンド</span></span>
<span class="line"><span>  → フレームバッファ (VRAM) → Present → 画面</span></span></code></pre></div></li><li><strong>座標変換の実装(第10章の回収)</strong><ul><li>モデル→ワールド→ビュー→クリップ→NDC→スクリーン</li><li>w除算と透視補正補間、深度値の非線形性(Zファイティングの原因)</li></ul></li><li><strong>シェーダプログラミング(HLSL中心、GLSL併記)</strong><ul><li>セマンティクス、定数バッファ(cbuffer)、テクスチャとサンプラ</li><li>頂点シェーダ: MVP乗算、法線変換、スキニング(ボーン行列)</li><li>ピクセルシェーダ: テクスチャサンプリング、ライティング</li><li>シェーダのコンパイル経路: HLSL→DXC→<strong>DXIL</strong>(中間言語)→ ドライバ→GPU ISA(第11章の回収)。GLSL→SPIR-Vも同じ構図</li></ul></li><li><strong>ライティング</strong><ul><li>ランバート拡散(=内積!)、Blinn-Phongスペキュラ</li><li>法線マップ(接空間)、環境光</li><li><strong>PBRの概念</strong>(エネルギー保存・金属/粗さワークフロー、 Cook-Torranceの式は「読める」程度でよい)</li><li>シャドウマップ(深度を光源から描く、という発想の転換)</li></ul></li><li><strong>出力マージャの攻防</strong><ul><li>深度テスト(Zバッファ法)、early-Z、Zプリパス</li><li>アルファブレンドと<strong>描画順問題</strong>(半透明ソート、加算合成)</li><li>バックフェースカリング</li></ul></li><li><strong>テクスチャの実務</strong><ul><li>ミップマップ(なぜ必要か: エイリアシングとキャッシュ)、 フィルタリング(バイリニア/トライリニア/異方性)</li><li>sRGBとリニアワークフロー(第1章の回収。「暗くなる/白飛びする」の正体)</li><li>圧縮フォーマット(BC1-7)</li></ul></li><li><strong>レンダリング戦略(エンジンの設計判断)</strong><ul><li>フォワード / ディファード(Gバッファ)/ フォワード+</li><li>ポストプロセス(トーンマップ、ブルーム、TAA)の概観</li><li>現代トピックの地図: メッシュシェーダ、GPU駆動描画、 Nanite/Lumen(第17章)、レイトレ(発展編)</li></ul></li><li><strong>RenderDoc入門(以後の常用ツール)</strong><ul><li>フレームキャプチャ→イベントブラウザ→各ステージの入出力表示</li><li>テクスチャビューア、メッシュビューア、ピクセル履歴、シェーダデバッグ</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>パイプラインは流れ作業</strong> ── 各段の入出力を言えることが「理解」</li><li><strong>プログラマブル(VS/PS)と固定機能(ラスタ/OM)の分業</strong></li><li><strong>深度バッファ</strong> ── 3D描画を成立させている単純で偉大な仕組み</li><li><strong>補間</strong> ── 頂点で計算した値がピクセルに届く仕組み</li><li><strong>リニアワークフロー</strong> ── 色計算の正しさの土台</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>マテリアル/シェーダグラフの中身</td><td>生成されるのはこの章のシェーダ</td></tr><tr><td>半透明の前後関係バグ</td><td>ブレンドと描画順・深度書き込み</td></tr><tr><td>Zファイティング</td><td>深度精度・ニア/ファー設定</td></tr><tr><td>遠景がチラつく</td><td>ミップマップ・エイリアシング</td></tr><tr><td>「ピクセル負荷が高い」</td><td>PS・解像度・オーバードロー</td></tr><tr><td>ライトを増やすと重い→ディファード</td><td>レンダリング戦略</td></tr><tr><td>色味がsRGB設定で変わる</td><td>リニアワークフロー</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><strong>この章から「自作ミニレンダラ」が始まる。教材はLearnOpenGL (またはDirectX11)。APIの詳細は第13章で深めるので、ここでは 「パイプラインを動かして理解する」ことに集中する。</strong></p><ol><li><strong>ソフトウェアラスタライザ(強く推奨)</strong>: GPUを使わず、CPUだけで 三角形を塗るプログラムを書け(エッジ関数、重心座標補間、Zバッファ、 テクスチャ、簡単なシェーディング)。「ラスタライザが何をしているか」が 永久に自分のものになる。(教材: tinyrenderer)</li><li>LearnOpenGL(またはDX11版チュートリアル)で:三角形→テクスチャ→ MVP変換で回る立方体→ランバート+スペキュラ→法線マップ→ シャドウマップ まで進めよ。</li><li>各演習をRenderDocでキャプチャし、(a)頂点入力 (b)VS出力 (c)ラスタ後のPS入力 (d)OM後の出力 を確認する習慣をつけよ。</li><li>深度テストを切る/ブレンドを加算にする/カリングを反転する ── それぞれ画面がどう壊れるかを観察し、理由を説明せよ。</li><li>わざとZファイティングを起こし、ニアクリップを遠ざけて改善せよ。</li><li>Shadertoyでピクセルシェーダのみの作品(レイマーチング入門)を1つ書け (PSの理解が深まる遊び場として)。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li><strong>&quot;Real-Time Rendering 4th Edition&quot;</strong> ── リアルタイムCGの聖典。 2〜5章(パイプライン・シェーディング)をまず読む</li><li>『HLSLシェーダーの魔導書』── 和書のシェーダ入門</li><li>LearnOpenGL(learnopengl.com、無料・事実上の標準教材)</li><li>Fabian Giesen &quot;A trip through the Graphics Pipeline&quot;(第11章から継続)</li><li>『Unityシェーダープログラミングの教科書』── Unity併用者に</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>tinyrenderer</strong>(ssloy/tinyrenderer)── ソフトウェアラスタライザを 500行で書く伝説の教材。演習1の教材</li><li><strong>RenderDoc</strong>(baldurk/renderdoc)── 道具であり、ソースも読める</li><li><strong>bgfx</strong>(bkaradzic/bgfx)── クロスプラットフォームレンダラの見本</li><li>Google <strong>filament</strong> ── PBR実装の最高峰ドキュメント(Filament docs)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Cem Yuksel &quot;Introduction to Computer Graphics&quot;(ユタ大講義、無料)</li><li>Freya Holmér(シェーダ回)、The Cherno OpenGL シリーズ</li><li>SIGGRAPH &quot;Physically Based Shading&quot; コース(PBR原典、発展)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>tinyrenderer(写経対象)</li><li>filamentのシェーダ(shaders/src)── 製品品質PBRの実物</li><li>UE5 <code>Engine/Shaders/Private/BasePassPixelShader.usf</code> (「UEのマテリアルも結局HLSL」を確認。深追いは第17章)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>パイプラインの各段階を順に挙げ、プログラマブル/固定機能を区別せよ。</li><li>頂点シェーダとピクセルシェーダの実行回数はそれぞれ何に比例するか。</li><li>ラスタライザは何を入力し何を出力するか。「補間」とは何か。</li><li>Zバッファ法を説明せよ。半透明がZバッファだけで解決できないのはなぜか。</li><li>ミップマップが画質と性能の両方に効く理由は?</li><li>ランバート拡散の式を書け。内積の幾何的意味(第10章)との関係は?</li><li>フォワードとディファードの違い、それぞれの得意・不得意は?</li><li>sRGBテクスチャをリニア変換せずにライティングすると何が起きるか?</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「画面にゲームが表示される」の正体(毎フレーム)</span></span>
<span class="line"><span>────────────────────────────────────────────</span></span>
<span class="line"><span>エンジンが発行した数百〜数千のドローコールそれぞれについて:</span></span>
<span class="line"><span> 頂点バッファ→[IA]→[VS: MVP変換]→[ラスタ]→[PS: テクスチャ+ライト]</span></span>
<span class="line"><span> →[OM: 深度/ブレンド]→フレームバッファ</span></span>
<span class="line"><span>────────────────────────────────────────────</span></span>
<span class="line"><span> 不透明パス → スカイ → 半透明パス → ポストプロセス → UI</span></span>
<span class="line"><span> (エンジンはこの章の知識で描画パスを設計している)</span></span>
<span class="line"><span>RenderDocの1キャプチャ = この図を実物で眺める行為</span></span>
<span class="line"><span>UnityのShaderGraph/UEのマテリアルエディタ = この章のシェーダ生成UI</span></span></code></pre></div>`,34)])])}const g=l(s,[["render",t]]);export{u as __pageData,g as default};
